import{_ as e,c as t,o as a,a0 as o}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Sjabloon voor het stellen en bijhouden van doelen","description":"","frontmatter":{},"headers":[],"relativePath":"nl/goal-template.md","filePath":"nl/goal-template.md"}');const r=e({name:"nl/goal-template.md"},[["render",function(e,n,r,i,l,d){return a(),t("div",null,[...n[0]||(n[0]=[o('<h1 id="sjabloon-voor-het-stellen-en-bijhouden-van-doelen" tabindex="-1">Sjabloon voor het stellen en bijhouden van doelen <a class="header-anchor" href="#sjabloon-voor-het-stellen-en-bijhouden-van-doelen" aria-label="Permalink to &quot;Sjabloon voor het stellen en bijhouden van doelen&quot;">​</a></h1><h2 id="hoe-gebruik-je-deze-sjabloon" tabindex="-1">Hoe gebruik je deze sjabloon? <a class="header-anchor" href="#hoe-gebruik-je-deze-sjabloon" aria-label="Permalink to &quot;Hoe gebruik je deze sjabloon?&quot;">​</a></h2><p>Met deze sjabloon kunt u zinvolle doelen stellen en uw voortgang systematisch bijhouden. Kopieer de onderstaande secties naar uw favoriete formaat (Word, Google Docs, Excel, Google Sheets of een notitieboek).</p><div class="tip custom-block"><p class="custom-block-title">De filosofie achter het stellen van doelen</p><p><strong>Doelen zonder monitoring zijn slechts wensen. Monitoring zonder reflectie is slechts data.</strong> Deze template combineert beide: heldere doelstellingen met gestructureerde reflectie om continue verbetering te garanderen.</p></div><h2 id="sjabloon-voor-het-vaststellen-van-jaarlijkse-doelen" tabindex="-1">Sjabloon voor het vaststellen van jaarlijkse doelen <a class="header-anchor" href="#sjabloon-voor-het-vaststellen-van-jaarlijkse-doelen" aria-label="Permalink to &quot;Sjabloon voor het vaststellen van jaarlijkse doelen&quot;">​</a></h2><h3 id="kopieer-dit-gedeelte-naar-uw-document" tabindex="-1">Kopieer dit gedeelte naar uw document <a class="header-anchor" href="#kopieer-dit-gedeelte-naar-uw-document" aria-label="Permalink to &quot;Kopieer dit gedeelte naar uw document&quot;">​</a></h3><hr><p><strong>Year:</strong> ________</p><p><strong>My Pétanque Vision for This Year:</strong></p><p>(In one sentence, what do I want to achieve this year?)</p><hr><h3 id="_1-wedstrijddoelen" tabindex="-1">1. Wedstrijddoelen <a class="header-anchor" href="#_1-wedstrijddoelen" aria-label="Permalink to &quot;1. Wedstrijddoelen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Doeltype</th><th>Specifiek doel</th><th>Waarom dit belangrijk is</th><th>Succesindicator</th></tr></thead><tbody><tr><td><strong>Toernooiresultaten</strong></td><td>Voorbeeld: Top 8 in het Regionaal Kampioenschap</td><td>Om te bewijzen dat ik op regionaal niveau kan meedoen</td><td>Plaatsing in de top 8</td></tr><tr><td><strong>Ranglijst</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Consistentie</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Teamprestaties</strong></td><td></td><td></td><td></td></tr></tbody></table><ol start="2"><li>Technische doelstellingen</li></ol><table tabindex="0"><thead><tr><th>Vaardigheidsgebied</th><th>Huidig niveau (1-10)</th><th>Doelniveau</th><th>Specifieke focus</th></tr></thead><tbody><tr><td><strong>Richtnauwkeurigheid</strong></td><td></td><td></td><td>Voorbeeld: 70% binnen 10 cm op 7 m</td></tr><tr><td><strong>Schietconsistentie</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Terreinaanpassing</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Opnameselectie</strong></td><td></td><td></td><td></td></tr></tbody></table><ol start="3"><li>Mentale speldoelen</li></ol><table tabindex="0"><thead><tr><th>Gebied</th><th>Huidige situatie</th><th>Doelsituatie</th><th>Oefenmethode</th></tr></thead><tbody><tr><td><strong>Drukbeheer</strong></td><td></td><td></td><td>Voorbeeld: Gebruik een reset van 3 ademhalingen vóór elke opname</td></tr><tr><td><strong>Innerlijke criticus</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Focus/Concentratie</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Zelfvertrouwen</strong></td><td></td><td></td><td></td></tr></tbody></table><ol start="4"><li>Fysieke doelen</li></ol><table tabindex="0"><thead><tr><th>Gebied</th><th>Huidig</th><th>Doel</th><th>Actieplan</th></tr></thead><tbody><tr><td><strong>Fitheidsniveau</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Flexibiliteit</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Uithoudingsvermogen</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Blessurepreventie</strong></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="quarterly-review-template" tabindex="-1">Quarterly Review Template <a class="header-anchor" href="#quarterly-review-template" aria-label="Permalink to &quot;Quarterly Review Template&quot;">​</a></h2><h3 id="copy-this-section-every-3-months" tabindex="-1">Copy This Section Every 3 Months <a class="header-anchor" href="#copy-this-section-every-3-months" aria-label="Permalink to &quot;Copy This Section Every 3 Months&quot;">​</a></h3><hr><p><strong>Kwartaal:</strong> Q1 / Q2 / Q3 / Q4 <strong>Revisiedatum:</strong> ________</p><p>Wat ging er goed?</p><ol><li></li><li></li><li></li></ol><p>Wat ging er niet volgens plan?</p><ol><li></li><li></li><li></li></ol><p>Belangrijkste leerpunten</p><ol><li></li><li></li><li></li></ol><h3 id="aanpassingen-voor-het-volgende-kwartaal" tabindex="-1">Aanpassingen voor het volgende kwartaal <a class="header-anchor" href="#aanpassingen-voor-het-volgende-kwartaal" aria-label="Permalink to &quot;Aanpassingen voor het volgende kwartaal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Doelgebied</th><th>Oorspronkelijk doel</th><th>Benodigde aanpassing</th><th>Nieuw doel</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="monthly-goal-template" tabindex="-1">Monthly Goal Template <a class="header-anchor" href="#monthly-goal-template" aria-label="Permalink to &quot;Monthly Goal Template&quot;">​</a></h2><h3 id="copy-this-section-each-month" tabindex="-1">Copy This Section Each Month <a class="header-anchor" href="#copy-this-section-each-month" aria-label="Permalink to &quot;Copy This Section Each Month&quot;">​</a></h3><hr><p><strong>Maand:</strong> ________ <strong>Jaar:</strong> ________</p><h3 id="focus-van-deze-maand" tabindex="-1">Focus van deze maand <a class="header-anchor" href="#focus-van-deze-maand" aria-label="Permalink to &quot;Focus van deze maand&quot;">​</a></h3><p><strong>Hoofddoel:</strong></p><p><strong>Waarom deze maand:</strong></p><h3 id="wekelijkse-analyse" tabindex="-1">Wekelijkse analyse <a class="header-anchor" href="#wekelijkse-analyse" aria-label="Permalink to &quot;Wekelijkse analyse&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Week</th><th>Specifiek doel</th><th>Trainingsfocus</th><th>Wedstrijd/Test</th></tr></thead><tbody><tr><td><strong>Week 1</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Week 2</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Week 3</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Week 4</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="maandelijkse-statistieken-om-bij-te-houden" tabindex="-1">Maandelijkse statistieken om bij te houden <a class="header-anchor" href="#maandelijkse-statistieken-om-bij-te-houden" aria-label="Permalink to &quot;Maandelijkse statistieken om bij te houden&quot;">​</a></h3><ul><li>[ ] Voltooide trainingssessies: _____ / _____</li><li>[ ] Deelgenomen wedstrijden: _____ / _____</li><li>[ ] Mentale training oefening: _____ dagen</li><li>[ ] Fysieke conditie: _____ sessies</li><li>[ ] Reflectie/dagboek bijhouden: _____ vermeldingen</li></ul><hr><h2 id="weekly-planning-template" tabindex="-1">Weekly Planning Template <a class="header-anchor" href="#weekly-planning-template" aria-label="Permalink to &quot;Weekly Planning Template&quot;">​</a></h2><h3 id="copy-this-section-each-week" tabindex="-1">Copy This Section Each Week <a class="header-anchor" href="#copy-this-section-each-week" aria-label="Permalink to &quot;Copy This Section Each Week&quot;">​</a></h3><hr><p><strong>Week van:</strong> ________</p><h3 id="voornemen-voor-deze-week" tabindex="-1">Voornemen voor deze week <a class="header-anchor" href="#voornemen-voor-deze-week" aria-label="Permalink to &quot;Voornemen voor deze week&quot;">​</a></h3><p>(Wat is mijn belangrijkste focus deze week?)</p><h3 id="trainingsschema" tabindex="-1">Trainingsschema <a class="header-anchor" href="#trainingsschema" aria-label="Permalink to &quot;Trainingsschema&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dag</th><th>Activiteit</th><th>Duur</th><th>Focusgebied</th><th>Notities</th></tr></thead><tbody><tr><td><strong>Maandag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Dinsdag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Woensdag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Donderdag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Vrijdag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Zaterdag</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Zondag</strong></td><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="wekelijkse-doelen" tabindex="-1">Wekelijkse doelen <a class="header-anchor" href="#wekelijkse-doelen" aria-label="Permalink to &quot;Wekelijkse doelen&quot;">​</a></h3><ul><li>[ ] Technische praktijk: _____ uur</li><li>[ ] Competitie/wedstrijdspel: _____ uur</li><li>[ ] Mentale training: _____ minuten</li><li>[ ] Fysieke training: _____ sessies</li><li>[ ] Videoanalyse: _____ sessies</li></ul><hr><h2 id="progress-tracking-sheet" tabindex="-1">Progress Tracking Sheet <a class="header-anchor" href="#progress-tracking-sheet" aria-label="Permalink to &quot;Progress Tracking Sheet&quot;">​</a></h2><h3 id="copy-this-to-excel-google-sheets" tabindex="-1">Copy This to Excel/Google Sheets <a class="header-anchor" href="#copy-this-to-excel-google-sheets" aria-label="Permalink to &quot;Copy This to Excel/Google Sheets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Goal Area</th><th>Target</th><th>Actual</th><th>Notes</th><th>Feeling (1-10)</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Instructions for Spreadsheet:</strong></p><ol><li>Create columns: Date, Goal Area, Target, Actual, Notes, Feeling</li><li>Add new row after each training session or competition</li><li>Use conditional formatting: Green if Actual ≥ Target, Yellow if close, Red if far off</li><li>Create charts to visualize progress over time</li></ol><hr><h2 id="prestatietracker-voor-wedstrijden" tabindex="-1">Prestatietracker voor wedstrijden <a class="header-anchor" href="#prestatietracker-voor-wedstrijden" aria-label="Permalink to &quot;Prestatietracker voor wedstrijden&quot;">​</a></h2><h3 id="kopieer-dit-om-de-toernooiresultaten-bij-te-houden" tabindex="-1">Kopieer dit om de toernooiresultaten bij te houden <a class="header-anchor" href="#kopieer-dit-om-de-toernooiresultaten-bij-te-houden" aria-label="Permalink to &quot;Kopieer dit om de toernooiresultaten bij te houden&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datum</th><th>Toernooi</th><th>Bereikte ronde</th><th>Plaatsing</th><th>Belangrijkste sterke punten</th><th>Verbeterpunten</th><th>Mentale toestand (1-10)</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="goal-achievement-celebration" tabindex="-1">Goal Achievement Celebration <a class="header-anchor" href="#goal-achievement-celebration" aria-label="Permalink to &quot;Goal Achievement Celebration&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Celebrate Progress!</p><p><strong>Every goal achieved deserves recognition.</strong> When you hit a target:</p><ol><li>✅ Mark it complete</li><li>🎉 Acknowledge the effort it took</li><li>📝 Write what you learned</li><li>🎯 Set the next challenge</li></ol></div><h3 id="achievement-log" tabindex="-1">Achievement Log <a class="header-anchor" href="#achievement-log" aria-label="Permalink to &quot;Achievement Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Goal Achieved</th><th>What It Took</th><th>Key Learning</th><th>Next Challenge</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="tips-voor-effectieve-doelstellingen" tabindex="-1">Tips voor effectieve doelstellingen <a class="header-anchor" href="#tips-voor-effectieve-doelstellingen" aria-label="Permalink to &quot;Tips voor effectieve doelstellingen&quot;">​</a></h2><h3 id="_1-begin-klein-bouw-momentum-op" tabindex="-1">1. Begin klein, bouw momentum op <a class="header-anchor" href="#_1-begin-klein-bouw-momentum-op" aria-label="Permalink to &quot;1. Begin klein, bouw momentum op&quot;">​</a></h3><p>Stel niet meteen 20 doelen. Begin met:</p><ul><li><strong>1 wedstrijddoel</strong></li><li><strong>1 technisch doel</strong></li><li><strong>1 mentaal speldoel</strong></li></ul><p>Beheers deze gegevens eerst voordat je er meer toevoegt.</p><h3 id="_2-regelmatig-evalueren" tabindex="-1">2. Regelmatig evalueren <a class="header-anchor" href="#_2-regelmatig-evalueren" aria-label="Permalink to &quot;2. Regelmatig evalueren&quot;">​</a></h3><ul><li><strong>Dagelijks:</strong> Controleer je intentie voor vandaag.</li><li><strong>Wekelijks:</strong> Bespreek de voortgang van de week en plan de volgende week.</li><li><strong>Maandelijks:</strong> Evalueer de maandelijkse doelstellingen en pas deze indien nodig aan.</li><li><strong>Kwartaal:</strong> Diepgaande reflectie, grote aanpassingen</li><li><strong>Jaarlijks:</strong> Vier het jaar, stel een nieuwe visie vast</li></ul><ol start="3"><li>Wees eerlijk, niet hard</li></ol><p>Als je een doel mist:</p><ul><li>❌ <strong>Niet doen:</strong> &quot;Ik ben vreselijk, ik zal nooit beter worden&quot;</li><li>✅ <strong>Doe:</strong> &quot;Wat stond er in de weg? Wat kan ik aanpassen?&quot;</li></ul><h3 id="_4-koppel-je-doelen-aan-je-waarom" tabindex="-1">4. Koppel je doelen aan je waarom. <a class="header-anchor" href="#_4-koppel-je-doelen-aan-je-waarom" aria-label="Permalink to &quot;4. Koppel je doelen aan je waarom.&quot;">​</a></h3><p>Elk doel moet aansluiten op je diepere motivatie:</p><ul><li>Waarom speel je pétanque? Wat betekent verbetering voor jou?</li><li>Hoe zal het voelen om dit doel te bereiken?</li></ul><ol start="5"><li>Maak het zichtbaar</li></ol><ul><li>Print je jaarlijkse doelen uit en hang ze op een plek waar je ze dagelijks ziet.</li><li>Stel telefoonherinneringen in voor wekelijkse evaluaties</li><li>Deel je doelen met je trainingspartner voor wederzijdse verantwoording.</li></ul><hr><h2 id="digital-vs-paper-tracking" tabindex="-1">Digital vs. Paper Tracking <a class="header-anchor" href="#digital-vs-paper-tracking" aria-label="Permalink to &quot;Digital vs. Paper Tracking&quot;">​</a></h2><h3 id="digital-google-sheets-excel" tabindex="-1">Digital (Google Sheets/Excel) <a class="header-anchor" href="#digital-google-sheets-excel" aria-label="Permalink to &quot;Digital (Google Sheets/Excel)&quot;">​</a></h3><p><strong>Pros:</strong></p><ul><li>Easy to update anywhere</li><li>Automatic calculations and charts</li><li>Can share with coach/training partner</li><li>Search and filter data</li></ul><p><strong>Cons:</strong></p><ul><li>Requires device</li><li>Can feel impersonal</li><li>Easy to ignore notifications</li></ul><h3 id="paper-notebook-printed-templates" tabindex="-1">Paper (Notebook/Printed Templates) <a class="header-anchor" href="#paper-notebook-printed-templates" aria-label="Permalink to &quot;Paper (Notebook/Printed Templates)&quot;">​</a></h3><p><strong>Pros:</strong></p><ul><li>Tactile, personal connection</li><li>No distractions</li><li>Easy to review during training</li><li>Satisfying to check boxes</li></ul><p><strong>Cons:</strong></p><ul><li>Can&#39;t easily create charts</li><li>Risk of losing notebook</li><li>Harder to share</li></ul><p><strong>Recommendation:</strong> Use both! Digital for data tracking, paper for daily intentions and reflections.</p><hr><h2 id="gerelateerde-bronnen" tabindex="-1">Gerelateerde bronnen <a class="header-anchor" href="#gerelateerde-bronnen" aria-label="Permalink to &quot;Gerelateerde bronnen&quot;">​</a></h2><ul><li><a href="/en/workshop">Workshop</a> - Groepssessies over het stellen van doelen en mentale training</li><li><a href="/en/training-session">Trainingssessie</a> - Oefenen met verantwoordingspartners</li><li><a href="/en/education/mental-strength">Mentale kracht</a> - Ontwikkel de juiste mindset voor het behalen van doelen</li><li><a href="/en/diary-template">Trainingsdagboeksjabloon</a> - Dagelijkse oefening bijhouden</li></ul><hr><h2 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h2><p><strong>New to goal setting? Start here:</strong></p><ol><li><strong>Week 1:</strong> Set ONE monthly goal using SMART framework</li><li><strong>Week 2:</strong> Track daily progress in simple table</li><li><strong>Week 3:</strong> Do first weekly review</li><li><strong>Week 4:</strong> Adjust goal if needed, celebrate progress</li></ol><p><strong>After one month:</strong> Add quarterly and annual goals.</p><hr><p>::: Waarschuwing: Veelgemaakte fouten bij het stellen van doelen</p><ol><li><strong>Te veel doelen</strong> - De focus is verwaterd</li><li><strong>Te vaag</strong> - &quot;Beter worden&quot; is niet meetbaar.</li><li><strong>Geen tracking</strong> - Voortgang niet zichtbaar</li><li><strong>Geen beoordeling</strong> - Gemiste kansen om aanpassingen te maken.</li><li><strong>Alleen resultaat, geen proces</strong> - Focus op wat je kunt beheersen. :::</li></ol><hr><h2 id="download-templates" tabindex="-1">Download Templates <a class="header-anchor" href="#download-templates" aria-label="Permalink to &quot;Download Templates&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Copy-Paste Ready</p><p>All templates on this page are designed to be copied directly into:</p><ul><li>Microsoft Word</li><li>Google Docs</li><li>Microsoft Excel</li><li>Google Sheets</li><li>Notion</li><li>Any note-taking app</li></ul><p>Simply select the template section you want, copy (Ctrl+C / Cmd+C), and paste into your preferred tool.</p></div><p><strong>Start with these three:</strong></p><ol><li>Annual Goal Setting Template</li><li>Weekly Planning Template</li><li>Progress Tracking Sheet</li></ol><hr><p>Gebruik dit raamwerk om uw doelen specifiek en haalbaar te maken:</p><h3 id="smart-doelsjabloon" tabindex="-1">SMART-doelsjabloon <a class="header-anchor" href="#smart-doelsjabloon" aria-label="Permalink to &quot;SMART-doelsjabloon&quot;">​</a></h3><p><strong>S - Specifiek:</strong> (Wat wil ik precies bereiken?)</p><p><strong>M - Meetbaar:</strong> (Hoe weet ik of ik het bereikt heb?)</p><p><strong>A - Haalbaar:</strong> (Is dit realistisch gezien mijn huidige niveau en middelen?)</p><p><strong>R - Relevant:</strong> (Waarom is dit belangrijk voor mijn algehele visie?)</p><p><strong>T - Tijdsgebonden:</strong> (Wanneer zal ik dit bereiken?)</p><h3 id="voorbeeld-smart-doelen" tabindex="-1">Voorbeeld SMART-doelen <a class="header-anchor" href="#voorbeeld-smart-doelen" aria-label="Permalink to &quot;Voorbeeld SMART-doelen&quot;">​</a></h3><details class="details custom-block"><summary>Voorbeeld 1: Technisch doel</summary><p><strong>S - Specifiek:</strong> Verbeterde richtnauwkeurigheid op moeilijk terrein <strong>M - Meetbaar:</strong> Landen binnen 20 cm van cochonnet in 7 van de 10 pogingen <strong>A - Haalbaar:</strong> Momenteel op 4/10, dus 7/10 is een uitdaging maar realistisch. <strong>R - Relevant:</strong> Moeilijk terrein komt vaak voor bij regionale toernooien. <strong>T - Tijdsgebonden:</strong> Te behalen vóór het einde van het tweede kwartaal (30 juni)</p></details><details class="details custom-block"><summary>Voorbeeld 2: Wedstrijddoel</summary><p><strong>S - Specifiek:</strong> De halve finales bereiken in het clubkampioenschap <strong>M - Meetbaar:</strong> Eindigen in de top 4 van een toernooi met 32 deelnemers <strong>A - Haalbaar:</strong> Momenteel 8e-12e op de clubranglijst, verbetering is realistisch. <strong>R - Relevant:</strong> Bouwt zelfvertrouwen op en bewijst vooruitgang <strong>T - Tijdsgebonden:</strong> Het kampioenschap is op 15 september.</p></details><details class="details custom-block"><summary>Voorbeeld 3: Doel van het mentale spel</summary><p><strong>S - Specifiek:</strong> Beheers je innerlijke criticus tijdens een wedstrijd <strong>M - Meetbaar:</strong> Gebruik de Inner Coach-herkadering na elke misser. <strong>A - Haalbaar:</strong> De techniek geoefend tijdens de training. <strong>R - Relevant:</strong> Negatieve zelfpraat is mijn grootste belemmering. <strong>T - Tijdsgebonden:</strong> Consistent gebruik in de volgende 3 toernooien</p></details><hr>',128)])])}]]);export{n as __pageData,r as default};
